"""Regenerate the image fixtures used by the asset tests.

Run this only when a fixture must actually change. The generated bytes are committed
so that every later run works from identical input: asset normalization is then the
only thing that can decide the bytes a model is shown.

    .venv/Scripts/python demo/tests/fixtures/make_figures.py
"""
from pathlib import Path
from PIL import Image, ImageDraw, ImageFont

HERE = Path(__file__).resolve().parent
FONT = 'C:/Windows/Fonts/msyh.ttc'


def font(size):
    try:
        return ImageFont.truetype(FONT, size)
    except OSError:
        return ImageFont.load_default()


def probability_tree():
    """A worked P(A) tree: priors on the left branches, likelihoods on the right."""
    image = Image.new('RGB', (980, 560), 'white')
    draw = ImageDraw.Draw(image)
    title, body, small = font(26), font(21), font(17)

    draw.text((30, 24), '图 F-1  全概率公式的概率树示例', fill='#1a1a1a', font=title)
    draw.text((30, 62), '先验 P(Hᵢ) 写在左侧分支，似然 P(A|Hᵢ) 写在右侧分支', fill='#555555', font=small)

    rows = [('H₁ 甲班', '0.20', '0.05', '0.95'),
            ('H₂ 乙班', '0.30', '0.10', '0.90'),
            ('H₃ 丙班', '0.50', '0.08', '0.92')]
    top = 140
    gap = 130
    root_x, mid_x, leaf_x = 90, 400, 740
    draw.ellipse((root_x - 10, 300 - 10, root_x + 10, 300 + 10), fill='#333333')

    for index, (name, prior, hit, miss) in enumerate(rows):
        y = top + index * gap
        up, down = y - 26, y + 26
        draw.line((root_x, 300, mid_x, (up + down) // 2), fill='#888888', width=2)
        draw.text((150, (up + down) // 2 - 34), f'P({name.split()[0]}) = {prior}', fill='#0b5cad', font=small)
        draw.text((mid_x - 4, (up + down) // 2 - 14), name, fill='#1a1a1a', font=body)
        for target, label, color in ((up, f'A   {hit}', '#1d9e75'), (down, f'Ā   {miss}', '#a32d2d')):
            draw.line((mid_x + 96, (up + down) // 2, leaf_x, target), fill='#888888', width=2)
            draw.text((leaf_x + 8, target - 12), f'P({label.split()[0]}|{name.split()[0]}) = {label.split()[1]}',
                      fill=color, font=small)

    draw.line((40, 500, 940, 500), fill='#cccccc', width=1)
    terms = ' + '.join(f'{prior}×{hit}' for _, prior, hit, _ in rows)
    draw.text((40, 514), f'P(A) = {terms} = 0.010 + 0.030 + 0.040 = 0.080', fill='#1a1a1a', font=body)
    return image


def likelihood_table():
    """The same numbers as a summary table, so figure and table can be cross-checked."""
    image = Image.new('RGB', (980, 420), 'white')
    draw = ImageDraw.Draw(image)
    title, body = font(26), font(20)
    draw.text((30, 24), '图 F-2  例题数据表（与图 F-1 使用同一组数值）', fill='#1a1a1a', font=title)

    headers = ['班级', '先验 P(Hᵢ)', 'P(A|Hᵢ)', '乘积']
    data = [('H₁ 甲班', '0.20', '0.05', '0.010'),
            ('H₂ 乙班', '0.30', '0.10', '0.030'),
            ('H₃ 丙班', '0.50', '0.08', '0.040')]
    columns = [60, 300, 540, 760]
    top = 110
    row_height = 62
    draw.rectangle((40, top - 40, 940, top), outline='#bbbbbb', width=1)
    for column, header in zip(columns, headers):
        draw.text((column, top - 34), header, fill='#333333', font=body)
    for index, row in enumerate(data):
        y = top + index * row_height
        draw.line((40, y, 940, y), fill='#dddddd', width=1)
        for column, value in zip(columns, row):
            color = '#1a1a1a' if column == columns[0] else '#0b5cad'
            draw.text((column, y + 16), value, fill=color, font=body)
    bottom = top + len(data) * row_height
    draw.line((40, bottom, 940, bottom), fill='#bbbbbb', width=1)
    draw.text((columns[0], bottom + 18), '合计 P(A) = 0.080', fill='#1a1a1a', font=body)
    return image


def main():
    tree, table = probability_tree(), likelihood_table()
    tree.save(HERE / 'probability-tree.png', format='PNG')
    table.save(HERE / 'likelihood-table.png', format='PNG')
    # Both drawings in one PDF: this is the kind of file a teacher actually uploads.
    tree.save(HERE / 'bayes-figures.pdf', format='PDF', save_all=True,
              append_images=[table], resolution=110.0)
    for name in ('probability-tree.png', 'likelihood-table.png', 'bayes-figures.pdf'):
        path = HERE / name
        print(f'{name}: {path.stat().st_size} bytes')


if __name__ == '__main__':
    main()
